    Object.assign(translations, {"heroKicker": ["Websites & process automation", "Webs y automatización de procesos"], "hero1": ["Stand out online.", "Destaca en la web."], "hero2": ["Work smarter.", "Trabaja mejor."], "hero3": ["That works.", "Así se avanza."], "heroText": ["A website that represents your business. Processes with less manual work. I help with custom web design and business automation using Microsoft Power Platform.", "Una web que representa tu negocio. Procesos con menos trabajo manual. Te ayudo con diseño web a medida y automatizaciones con Microsoft Power Platform."], "heroNote": ["Websites from €50/month excl. VAT · Automation starts with a free introduction", "Webs desde 50 €/mes sin IVA · Automatización: primera charla gratuita"], "servicesKicker": ["01 / Custom websites", "01 / Webs a medida"], "pricingKicker": ["Website plans", "Planes web"], "pricingTitle": ["Your website.\nOne clear monthly price.", "Tu web.\nUna cuota mensual clara."], "processKicker": ["How we build your website", "Así creamos tu web"], "aboutKicker": ["Your direct point of contact", "Tu contacto directo"], "aboutTitle": ["From first idea\nto a working solution.", "De la primera idea\na una solución real."], "aboutText": ["You work directly with me: Justin. With my background in ICT and project management, I help business owners build a stronger website and a smarter way of working.", "Trabajas directamente conmigo: Justin. Con mi experiencia en TIC y gestión de proyectos, ayudo a crear una web sólida y una forma de trabajar más eficiente."], "aboutText2": ["I look at what your business needs. Sometimes it is a new website; sometimes a process that takes too much time. We start with the goal and build from there.", "Partimos de lo que necesita tu negocio: una nueva web o un proceso que consume demasiado tiempo. Definimos el objetivo y avanzamos desde ahí."], "contactText": ["A new website or less manual work? Tell me what you need. For process automation, we start with a free 20-minute virtual coffee.", "¿Una nueva web o menos trabajo manual? Cuéntame qué necesitas. Para automatizar procesos, empezamos con un café virtual gratuito de 20 minutos."], "trust4": ["Web design & Power Platform", "Diseño web y Power Platform"], "trust2": ["From design to delivery", "Del diseño a la ejecución"], "automationNav": ["Automation", "Automatización"], "heroWeb": ["I need a website", "Quiero una web"], "heroAuto": ["I want to work smarter", "Quiero trabajar mejor"], "routesKicker": ["Two services. One committed partner.", "Dos servicios. Un único contacto."], "routeWebTitle": ["A website\nthat works for you.", "Una web\nque trabaja para ti."], "routeWebText": ["From first impression to enquiry. Custom design, hosting and maintenance from €50 per month.", "De la primera impresión a la consulta. Diseño a medida, hosting y mantenimiento desde 50 € al mes."], "routeWebLink": ["Explore website plans ↗", "Descubre los planes web ↗"], "routeAutoTitle": ["Less manual work.\nMore room to grow.", "Menos trabajo manual.\nMás posibilidades."], "routeAutoText": ["Find opportunities in your office processes. Then build focused automations with Microsoft Power Platform.", "Identificamos oportunidades en tus procesos de oficina y automatizamos con Microsoft Power Platform."], "routeAutoLink": ["Start with a free conversation ↗", "Empieza con una charla gratuita ↗"], "acoffeePrice": ["Free · Online · 20 minutes", "Gratis · Online · 20 minutos"], "acoffeeTitle": ["First, a virtual\ncup of coffee.", "Primero, un\ncafé virtual."], "acoffeeText": ["In a 20-minute online conversation, we discuss your business, daily work and bottlenecks. Together we decide whether a process analysis is a useful next step.", "En una charla online de 20 minutos hablamos de tu negocio, tareas y dificultades. Vemos si un análisis de procesos es el siguiente paso adecuado."], "coffeeVisual": ["Your story.\nMy full attention.", "Tu historia.\nToda mi atención."], "journeyTab0": ["Introduction", "Introducción"], "aofficePrice": ["Free · Online or at your office", "Gratis · Online o en tu oficina"], "aofficeTitle": ["Step back.\nThen look closer.", "Tomamos perspectiva.\nDespués, profundizamos."], "aofficeText": ["A free morning or afternoon, online or in person at your office. We map your processes and identify quick wins: practical opportunities where a first automation could add value.", "Una mañana o tarde gratuita, online o presencial en tu oficina. Analizamos los procesos y buscamos oportunidades concretas donde una primera automatización pueda aportar valor."], "map1": ["Daily tasks", "Tareas diarias"], "map2": ["Bottlenecks", "Obstáculos"], "map3": ["Opportunities & value", "Oportunidades y valor"], "journeyTab1": ["Process analysis", "Análisis"], "areportPrice": ["€1,500 · Advisory report", "1.500 € · Informe de asesoramiento"], "areportTitle": ["From insight\nto a clear plan.", "Del análisis\na un plan claro."], "areportText": ["With your approval, I turn the findings into a report with concrete actions, improvement proposals and a reasoned order for the first automations.", "Con tu aprobación, elaboro un informe con acciones concretas, propuestas de mejora y un orden justificado para las primeras automatizaciones."], "reportPreviewTitle": ["From analysis\nto action.", "Del análisis\na la acción."], "reportPreviewFoot": ["Priorities · Actions · Proposals", "Prioridades · Acciones · Propuestas"], "journeyTab2": ["Advisory report", "Informe"], "abuildPrice": ["Implementation · Quoted separately", "Ejecución · Presupuesto aparte"], "abuildTitle": ["Now we\nmake it work.", "Ahora lo\nhacemos realidad."], "abuildText": ["We choose the first processes and agree the scope, timeline and costs. Then we build, test and refine the automations using Microsoft Power Platform.", "Elegimos los primeros procesos y acordamos alcance, planificación y costes. Después creamos, probamos y mejoramos las automatizaciones con Microsoft Power Platform."], "flow1": ["Request received", "Solicitud recibida"], "flow2": ["Request approval", "Solicitar aprobación"], "flow3": ["Route the task automatically", "Asignar la tarea automáticamente"], "flowCaption": ["Example of a possible automation", "Ejemplo de una posible automatización"], "journeyTab3": ["Automation", "Automatización"], "autoKicker": ["02 / Process improvement & automation", "02 / Mejora y automatización de procesos"], "autoTitle": ["Your people have\nmore to do than retype.", "Tu equipo tiene más\nque hacer que copiar datos."], "autoIntro": ["Copying information, chasing approvals, manually routing tasks. Let’s find out which recurring tasks can work better.", "Copiar datos, perseguir aprobaciones, asignar tareas a mano. Veamos qué tareas repetitivas pueden hacerse mejor."], "coffeeCta": ["Book your free virtual coffee", "Reserva tu café virtual gratuito"], "journeyHeading": ["From first conversation to smarter work.", "De la primera charla a trabajar mejor."], "skipJourney": ["Skip to the advisory report ↓", "Ir al informe ↓"], "reportKicker": ["Concrete next steps, not a loose list of ideas", "Próximos pasos concretos, no solo ideas"], "reportTitle": ["Know where\nto begin.", "Sabrás por\ndónde empezar."], "reportIntro": ["After the free process analysis, you can choose the paid advisory report. It gives you a clear starting point before implementation begins.", "Tras el análisis gratuito, puedes optar por el informe de pago. Tendrás un punto de partida claro antes de iniciar la ejecución."], "deliver1": ["Overview of the office processes examined and their bottlenecks", "Resumen de los procesos analizados y sus obstáculos"], "deliver2": ["Opportunities for initial automations and their expected value", "Oportunidades de automatización y su valor esperado"], "deliver3": ["Concrete improvement proposals, ordered by priority", "Propuestas concretas de mejora, ordenadas por prioridad"], "deliver4": ["Action items and a proposal for next steps", "Acciones y una propuesta de próximos pasos"], "reportOfferLabel": ["Process analysis & advice", "Análisis y asesoramiento"], "freeStep1": ["Virtual conversation · 20 minutes", "Charla virtual · 20 minutos"], "freeWord": ["Free", "Gratis"], "freeStep2": ["Process analysis · Morning or afternoon · Online or at your office", "Análisis · Mañana o tarde · Online o en tu oficina"], "reportCostLabel": ["One-off advisory report fee, excl. VAT", "Pago único por el informe, sin IVA"], "reportCta": ["Start with a free introduction", "Empieza con una charla gratuita"], "reportNote": ["The report is prepared after your approval. Automations, implementation and any Microsoft licences are outside this fee and agreed separately.", "El informe se prepara con tu aprobación. Automatizaciones, implementación y posibles licencias de Microsoft no están incluidas y se acuerdan aparte."], "examplesKicker": ["Where could the first value be?", "¿Dónde puede estar el primer valor?"], "examplesTitle": ["Start small.\nImprove with purpose.", "Empieza por algo pequeño.\nMejora con un objetivo."], "examplesText": ["These are examples of processes we can investigate. The analysis determines what fits your organisation.", "Son ejemplos de procesos que podemos analizar. El análisis determina qué encaja con tu organización."], "exampleTitle0": ["Requests & approvals", "Solicitudes y aprobaciones"], "exampleText0": ["Route requests to the right people for approval and pass on follow-up tasks automatically.", "Envía solicitudes a las personas adecuadas y asigna automáticamente las tareas posteriores."], "exampleTitle1": ["Simpler data entry", "Registro más sencillo"], "exampleText1": ["A practical app for checks, records or internal requests, tailored to the way your team works.", "Una app práctica para controles, registros o solicitudes internas, adaptada a tu equipo."], "exampleTitle2": ["Visibility into progress", "Visibilidad del progreso"], "exampleText2": ["See where work gets stuck and which steps need attention, using the data available.", "Identifica dónde se acumula trabajo y qué pasos necesitan atención con los datos disponibles."], "faqAuto0q": ["What exactly is free?", "¿Qué es exactamente gratuito?"], "faqAuto0a": ["The 20-minute online introduction is free. A morning or afternoon of process analysis is also free, either online or in person at your office. The subsequent report costs €1,500 excl. VAT and is prepared only with your approval.", "La charla online de 20 minutos es gratuita. También lo es una mañana o tarde de análisis, online o presencial en tu oficina. El informe posterior cuesta 1.500 € sin IVA y se prepara con tu aprobación."], "faqAuto1q": ["Is implementation included in the report?", "¿La implementación está incluida en el informe?"], "faqAuto1a": ["No. The report provides findings, action items and proposals. We separately agree the scope, timeline and costs for building and implementing the automations.", "No. El informe aporta conclusiones, acciones y propuestas. El alcance, la planificación y los costes de implementación se acuerdan por separado."], "faqAuto2q": ["Do I need Microsoft licences already?", "¿Necesito tener licencias de Microsoft?"], "faqAuto2a": ["Not for the introduction. During the analysis, we discuss your current environment. Required licences and integrations depend on the solution and are agreed before implementation.", "Para la primera charla, no. Durante el análisis revisamos tu entorno. Las licencias e integraciones dependen de la solución y se acuerdan antes de empezar."], "interestLabel": ["What would you like to discuss?", "¿De qué quieres hablar?"], "interestWeb": ["A custom website", "Una web a medida"], "interestAuto": ["Business process automation", "Automatización de procesos"], "interestBoth": ["Both / not sure yet", "Ambos / todavía no lo sé"]});
