    function deleteAnalyticsCookies(){
      const domains=location.hostname.split('.');
      const paths=location.pathname.split('/').slice(0,-1).map((_,i,a)=>'/'+a.slice(1,i+1).join('/'));
      document.cookie.split(';').forEach(cookie=>{const name=cookie.split('=')[0].trim();if(!/^_ga($|_)/.test(name))return;for(const path of new Set(['/',...paths])){const base=name+'=; Max-Age=0; path='+path+';';document.cookie=base;for(let i=0;i<domains.length-1;i++)document.cookie=base+' domain=.'+domains.slice(i).join('.')+';';}});
    }
    function setConsent(allow){
      storage.set('sd-analytics',allow?'granted':'denied');consent.hidden=true;
      if(allow)enableAnalytics();else{window['ga-disable-'+GA_ID]=true;if(window.gtag)window.gtag('consent','update',{analytics_storage:'denied'});deleteAnalyticsCookies();if(analyticsLoaded)location.reload();}
      document.getElementById('cookieSettings').focus({preventScroll:true});
    }
    document.getElementById('acceptCookies').addEventListener('click',()=>setConsent(true));
    document.getElementById('rejectCookies').addEventListener('click',()=>setConsent(false));
    document.getElementById('cookieSettings').addEventListener('click',()=>{consent.hidden=false;document.getElementById('rejectCookies').focus({preventScroll:true});});
    if(storage.get('sd-analytics')==='granted')enableAnalytics();

    document.addEventListener('click',event=>{
      const a=event.target.closest('a');
      if(!a||storage.get('sd-analytics')!=='granted'||!window.gtag)return;
      const method=(a.classList.contains('wa-link')||a.dataset.toolContact)?'whatsapp':a.href.startsWith('mailto:')?'email':a.href.startsWith('tel:')?'phone':null;
      if(method)window.gtag('event','contact_click',{contact_method:method,service:selectedView,transport_type:'beacon'});
    });
    document.querySelector('.contact-form')?.addEventListener('submit',()=>{
      if(storage.get('sd-analytics')==='granted'&&window.gtag)window.gtag('event','enquiry_form_submit',{service:selectedView,transport_type:'beacon'});
    });
    // Keep the first visit focused on the website; settings are always available.
    if(!storage.get('sd-analytics'))setTimeout(()=>{consent.hidden=false;},2500);
  